UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=683200, `RewardSpell`=0, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `FlagsEx2`=0, `QuestDescription`='After the meeting in Harandar, I came here to speak with Zul\'jarra about the vision you witnessed. Zul\'jan had seemed upset when you left and it was not my intent to make him so.\r\n\r\nBut all of that can wait. Now that you\'re awake, you should go speak to Zul\'jarra. She wants to know what happened at Atal\'Aman.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='I have already sent scouts to search for Zul\'jan, but it will be impossible to cover so much ground. I pray he sees through de lies dat Malacrass has woven before it\'s too late.\n\nThank you, , for telling me what happened and for being with my uncle at de end.\n\nDis eagle was my uncle\'s favorite companion on his walks through Zul\'Aman. I think he would like it if you took care of him now dat he\'s gone.', `VerifiedBuild`=58162 WHERE `ID`=93012;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=683200, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `QuestDescription`='If Malacrass was right, de key to Ula\'tek should be right here.\r\n\r\n<Zul\'jan\'s heavy hammer thumps onto the shrine for emphasis.>\r\n\r\nIt may take me some time to break through de stone to find it.\r\n\r\nI don\'t know what kind of protection de ancestors have in place, but you will have to deal with dem while I work.\r\n\r\nI admit, I did not believe de visions in Harandar. I don\'t fully trust Malacrass\'s notes either.\r\n\r\nBut if de key is here, dat would be undeniable proof dat what we are chasing is real.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='', `VerifiedBuild`=58162 WHERE `ID`=93011;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardBonusMoney`=34100, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `QuestDescription`='Here! De note says Ula\'tek was sealed away by de Amani. To break de seal, one needs a \"key.\"\r\n\r\n<Zul\'jan flips through the notes.>\r\n\r\nDe key was hidden within a shrine and protected with ancient magic. But which shrine... \r\n\r\n<Zul\'jan looks up.>\r\n\r\nDidn\'t de tablets at Numazon mention a shrine bein\' \"dedicated to de serpent\'s victory?\" We know from de visions in Harandar dat Ula\'tek was a serpent. \r\n\r\nDat must be it! De key is hidden at de serpent shrine in Atal\'Aman!', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='Dis shrine is ancient. Small. Unremarkable.\n\nDe perfect hiding place.', `VerifiedBuild`=58162 WHERE `ID`=93010;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=341600, `RewardSpell`=0, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `LogDescription`='Collect 8 Vilebranch Hex Fetishes from the Vilebranch trolls in Numazon.', `QuestDescription`='I wish I could be more help but... de gaps in my memory. Due to de damage de mask has sustained, dat magic has leaked out for who knows how long.\r\n\r\nYou repaired de physical parts of de mask, but de magic within is still weak.\r\n\r\nZul\'jan says Vilebranch trolls occupy this crypt. De magic dat binds me together is like de magic they use.\r\n\r\nYou might be able to help. Retrieve their hex fetishes--I should be able to drain the magic from them.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='It will just take a moment to drain de magic from de fetishes.', `VerifiedBuild`=58162 WHERE `ID`=92958;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=341600, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `LogDescription`='Take 6 rubbings of the Ancient Amani Tablets within Numazon.', `QuestDescription`='If de tablets were made when de Amani first arrived in Zul\'Aman, den there must be some clue about Ula\'tek here.\r\n\r\nDe tablets are too heavy to carry, so Uncle suggested dat we take rubbings of de inscriptions.\r\n\r\nI scouted ahead and gathered a few, but I ran into de Vilebranch. I came back here to make sure Uncle was safe.\r\n\r\nEnter Numazon and collect more of de rubbings while I watch over Uncle. Watch out for de Vilebranch.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='Look here! Dis mentions the Amani summoning a great serpent to save dem from a terrible foe.\n\nAnd here, de serpent was victorious but de Amani sealed it away.\n\nDe first shrine built in Atal\'Aman was dedicated to the serpent.', `VerifiedBuild`=58162 WHERE `ID`=92957;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardBonusMoney`=34100, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `QuestDescription`='De ancestors did not bow to a loa--dey claimed a weapon! A weapon dat led to our victory.\r\n\r\nI must know more.\r\n\r\nYou said de tablets at Numazon are de oldest in Zul\'Aman. We can continue de search there. Perhaps de ancient Amani left behind clues for us.\r\n\r\nUncle says we should bring de mask. A stray memory might be de key to unlocking dis mystery.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='Uncle does not understand. Ula\'tek could change everything.', `VerifiedBuild`=58162 WHERE `ID`=92955;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `SuggestedGroupNum`=0, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=1366400, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `PortraitGiver`=0, `LogDescription`='Collect Malacrass\'s Notes from Vordaza and complete the Maisara Caverns dungeon. A level 80 Quest (Dungeon). Rewards . Added in World of Warcraft: Midnight.', `QuestDescription`='Malacrass\'s notes are with Vordaza, and she\'s using them to further her necromantic experiments.\r\n\r\nI need you to go into de Maisara Caverns to recover them. It will be dangerous, and you will need to gather allies before venturing in.\r\n\r\nI will stay here and protect my uncle. We need to sort through all de scrolls we gathered and see what else we can find out.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='You got dem. Now let\'s see if dis was worth all de effort.', `VerifiedBuild`=58162 WHERE `ID`=92954;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=683200, `RewardSpell`=0, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `QuestDescription`='While I was a servant of de Vilebranch, I remember discussions about Malacrass\'s research into Ula\'tek.\r\n\r\nMalacrass recorded his knowledge in scrolls that he kept with him. Now that he\'s dead, we need to find out what happened to dem.\r\n\r\nDe Vilebranch hex masters won\'t talk willingly... but if you slay dem, I can use their own necromantic magic against dem to compel dem to speak.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='The Maisara Caverns are even more dangerous than de Deeps, and Vordaza is as deadly as she is cruel.', `VerifiedBuild`=58162 WHERE `ID`=92953;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardBonusMoney`=34100, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `LogDescription`='Meet the Befuddled Amani Mask outside Maisara Deeps.', `QuestDescription`='De magic helped, but... not enough. I still don\'t remember my name or past life. Dat knowledge may be lost forever...\r\n\r\nI do remember more about Ula\'tek--or rather, where we might find more information!\r\n\r\nI was forced into dis form by de Vilebranch trolls. Dey kept dark knowledge secret from de other tribes, includin\' knowledge of Ula\'tek.\r\n\r\nIf we are to know more, we must go to de Maisara Deeps.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='Malacrass is dead, but dat doesn\'t mean his knowledge is lost.', `VerifiedBuild`=58162 WHERE `ID`=92952;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=683200, `RewardSpell`=0, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `LogDescription`='Collect 8 Vilebranch Scrolls from Maisara Deeps.', `QuestDescription`='De mask says we are lookin\' for de scrolls of Malacrass. While we are in Maisara, try to find any scrolls de Vilebranch have left around.\r\n\r\nMaisara is a dangerous place, so don\'t bother sortin\' through dem--just grab \'em and we can check later.\r\n\r\nEven if dey don\'t mention Ula\'tek, we might find information about their plans or intentions against de Amani.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='', `VerifiedBuild`=58162 WHERE `ID`=92951;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=170800, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `QuestDescription`='My uncle has already started communin\' with de loa to find information on dis Ula\'tek. Meanwhile, we gonna dig through his boxes to see what we can find.\r\n\r\n<Zul\'jan points to all the boxes scattered around the terrace.>\r\n\r\nMy uncle has de biggest collection of histories among de Amani. I used to read through dem when I was a boy.\r\n\r\nLook for anything about Ula\'tek, snakes, or early Amani history. I\'ll take these, you search de others.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='Did you hear what it said? A weapon!', `VerifiedBuild`=58162 WHERE `ID`=92907;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardBonusMoney`=34100, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `QuestDescription`='I have heard de story since I was a child! De Amani were outnumbered and still dey fought on! Dey claimed victory through sheer will!\r\n\r\nOrweyna says de visions cannot lie. Uncle thinks details of de battle could have been lost. Dey would question everything it means to be Amani.\r\n\r\n<Zul\'jan scowls.>\r\n\r\nI must find de truth of dis. Uncle says if anyone would know, it would be de loa. De loa have said nothing of dis before, but we must start somewhere.\r\n\r\nIt\'s time to go home.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='Why is my uncle so disorganized?', `VerifiedBuild`=58162 WHERE `ID`=92904;
UPDATE `world`.`quest_template` SET `ContentTuningID`=0, `QuestInfoID`=5, `RewardXPDifficulty`=1, `RewardMoneyDifficulty`=1, `RewardBonusMoney`=341600, `RewardSpell`=0, `RewardArtifactXPDifficulty`=1, `RewardArtifactXPMultiplier`=0.0e0, `Flags`=0, `FlagsEx`=0, `FlagsEx2`=0, `QuestDescription`='Not all of the visions in this place were clear to us. Some of them were... strange.\r\n\r\nOne in particular seemed to revolve around an unfamiliar people: a people that we learned are the Amani trolls.\r\n\r\nThe magic used to create the painting, to pull the memories from the past, are tied to the haranir and those close to us. If there was no connection, the Zur\'ashar--who create the paintings--could not have recalled troll history.\r\n\r\nI can show you and Zul\'jan, and you can judge for yourselves.', `AreaDescription`=NULL, `PortraitGiverText`=NULL, `PortraitGiverName`=NULL, `PortraitTurnInText`=NULL, `PortraitTurnInName`=NULL, `QuestCompletionLog`='Amani history, painted on the walls of our ancestors. This magic does not work without a bond between our peoples.', `VerifiedBuild`=58162 WHERE `ID`=92901;
